# Let me try using the count value itself as output
# count_7 = 2 → output 2
# count_7 = 1 → output 4 (majority)

test_counts = {
    (0, 0): 2, (0, 1): 2,
    (1, 0): 1, (1, 1): 2,
    (2, 0): 2, (2, 1): 2,
    (3, 0): 1, (3, 1): 1,
}

output_try = []
for r in range(4):
    row = []
    for c in range(2):
        cnt = test_counts[(r,c)]
        if cnt == 1:
            row.append(4)  # majority
        else:
            row.append(cnt)  # count value?
    output_try.append(row)

print(f"Output using count value: {output_try}")

